using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Collect all errors
var errors = new List<(string Project, string File, int Line, int Col, string Code, string Message)>();

build.VisitAllChildren<Error>(error => {
    var project = "";
    var node = error.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    errors.Add((project, error.File ?? "", error.LineNumber, error.ColumnNumber, error.Code ?? "", error.Text ?? ""));
});

// Collect all warnings too for context
var warnings = new List<(string Project, string Code, string Message)>();
build.VisitAllChildren<Warning>(warning => {
    var project = "";
    var node = warning.Parent;
    while (node != null) {
        if (node is Project p) { project = p.Name; break; }
        node = node.Parent;
    }
    warnings.Add((project, warning.Code ?? "", warning.Text ?? ""));
});

Console.WriteLine($"=== BUILD ERRORS ({errors.Count} total) ===\n");
foreach (var g in errors.GroupBy(e => e.Project))
{
    Console.WriteLine($"Project: {g.Key}");
    foreach (var e in g)
    {
        Console.WriteLine($"  [{e.Code}] {e.File}({e.Line},{e.Col}): {e.Message}");
    }
    Console.WriteLine();
}

if (warnings.Count > 0)
{
    Console.WriteLine($"\n=== BUILD WARNINGS ({warnings.Count} total) ===\n");
    foreach (var g in warnings.GroupBy(w => w.Project))
    {
        Console.WriteLine($"Project: {g.Key}");
        foreach (var w in g)
        {
            Console.WriteLine($"  [{w.Code}] {w.Message}");
        }
        Console.WriteLine();
    }
}
EOF

