using Microsoft.Build.Logging.StructuredLogger;
using System;
using System.Linq;
using System.Collections.Generic;

var binlogPath = args[0];
var build = BinaryLog.ReadBuild(binlogPath);

// Get all messages that look like errors or important diagnostics
Console.WriteLine("=== ALL ERRORS AND DIAGNOSTICS ===\n");
build.VisitAllChildren<Error>(error => {
    var proj = error.Parent;
    while (proj != null && !(proj is Project)) proj = proj.Parent;
    Console.WriteLine($"[{(proj as Project)?.Name}] {error.Code} | {error.File}({error.LineNumber},{error.ColumnNumber})");
    Console.WriteLine($"  {error.Text}");
    Console.WriteLine();
});

// Get properties to understand project config
Console.WriteLine("\n=== KEY PROPERTIES (Services.csproj) ===\n");
build.VisitAllChildren<Property>(prop => {
    var proj = prop.Parent;
    while (proj != null && !(proj is Project)) proj = proj.Parent;
    var pname = (proj as Project)?.Name;
    if (pname == "Services.csproj" && (prop.Name == "TargetFramework" || prop.Name == "PackageReference"))
    {
        Console.WriteLine($"  {prop.Name} = {prop.Value}");
    }
});

// Look for source files to understand what's being compiled
